lign:start}.a852-news{grid-template-columns:1fr}.a852-news-featured{min-height:410px;padding:24px}.a852-news-featured h3{font-size:29px}.a852-news-list article{grid-template-columns:120px 1fr}.a852-footer-trust{grid-template-columns:1fr 1fr}.a852-footer-grid{grid-template-columns:1fr 1fr;gap:25px}.a852-footer-grid section:first-child{grid-column:1/-1}.a852-copy{display:block;text-align:center}.a852-copy span{display:block;margin:5px}.a852-language{display:none}.a852-listing-grid{grid-template-columns:1fr 1fr;gap:12px}.a852-detail{grid-template-columns:1fr}.a852-cart-line{grid-template-columns:70px 1fr}.a852-cart-line>:last-child{grid-column:2}.a852-services,.a852-process,.a852-promos,.a852-pricing,.a852-category-rail,.a852-products{scrollbar-width:none}.a852-services::-webkit-scrollbar,.a852-process::-webkit-scrollbar,.a852-promos::-webkit-scrollbar,.a852-pricing::-webkit-scrollbar,.a852-category-rail::-webkit-scrollbar,.a852-products::-webkit-scrollbar{display:none}}
